        self.expr = expr
        self.pos = 0
        self.current_char = self.expr[self.pos] if self.expr else None

    def error(self):
        raise Exception("Invalid expression")

    def advance(self):
        self.pos += 1
        if self.pos < len(self.expr):
            self.current_char = self.expr[self.pos]
        else:
            self.current_char = None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self):
        num_str = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            num_str += self.current_char
            self.advance()
        return float(num_str)

    def factor(self):
        if self.current_char == '(':
            self.advance()
            result = self.expr()
            if self.current_char == ')':
                self.advance()
                return result
            else:
                self.error()
        else:
            return self.number()

    def term(self):
        result = self.factor()
        while self.current_char is not None and self.current_char in ('*', '/'):
            if self.current_char == '*':
                self.advance()
                result *= self.factor()
            elif self.current_char == '/':
                self.advance()
                divisor = self.factor()
                if divisor == 0:
                    self.error()
                result /= divisor
        return result

    def expr(self):
        result = self.term()
        while self.current_char is not None and self.current_char in ('+', '-'):
            if self.current_char == '+':
                self.advance()
                result += self.term()
            elif self.current_char == '-':
                self.advance()
                result -= self.term()
        return result

