class ExpressionEvaluator:
    def __init__(self, expression):
        self.expression = expression
        self.position = 0

    def parse(self):
        tokens = self.tokenize(self.expression)
        self.position = 0
        return self.expr(tokens)

    def tokenize(self, expr):
        tokens = []
        current_number = ''
        for char in expr:
            if char in '0123456789.':
                current_number += char
            else:
                if current_number:
                    tokens.append(float(current_number))
                    current_number = ''
                if char in '+-*/()':
                    tokens.append(char)
        if current_number:
            tokens.append(float(current_number))
        return tokens

    def expr(self, tokens):
        result = self.term(tokens)
        while self.position < len(tokens) and tokens[self.position] in ('+', '-'):
            op = tokens[self.position]
            self.position += 1
            if op == '+':
                result += self.term(tokens)
            elif op == '-':
                result -= self.term(tokens)
        return result

    def term(self, tokens):
        result = self.factor(tokens)
        while self.position < len(tokens) and tokens[self.position] in ('*', '/'):
            op = tokens[self.position]
            self.position += 1
            if op == '*':
                result *= self.factor(tokens)
            elif op == '/':
                result /= self.factor(tokens)
        return result

    def factor(self, tokens):
        if tokens[self.position] == '(':
            self.position += 1
            result = self.expr(tokens)
            self.position += 1  # Skip past ')'
            return result
        else:
            number = tokens[self.position]
            self.position += 1
            return number

