class Parser:
    def __init__(self, expression: str):
        self.expression = expression
        self.position = 0
        self.current_char = self.expression[self.position] if self.expression else None

    def advance(self):
        """Advances the current position and updates the current character."""
        self.position += 1
        self.current_char = self.expression[self.position] if self.position < len(self.expression) else None

    def skip_whitespace(self):
        """Skips any whitespace characters in the expression."""
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self):
        """Parses a number from the expression."""
        num_str = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            num_str += self.current_char
            self.advance()
        return float(num_str)

    def factor(self):
        """Parses a factor in the expression, which can be a number or a parenthetical expression."""
        if self.current_char == '(':
            self.advance()
            result = self.expr()
            self.advance()  # skip ')'
            return result
        return self.number()

    def term(self):
        """Parses a term in the expression (factors combined with * or /)."""
        result = self.factor()
        while self.current_char in ('*', '/'):
            operation = self.current_char
            self.advance()
            if operation == '*':
                result *= self.factor()
            elif operation == '/':
                result /= self.factor()
        return result

    def expr(self):
        """Parses an expression (terms combined with + or -)."""
        result = self.term()
        while self.current_char in ('+', '-'):
            operation = self.current_char
            self.advance()
            if operation == '+':
                result += self.term()
            elif operation == '-':
                result -= self.term()
        return result

