    def factor(self):
        if self.current_char == '(':
            self.advance()
            result = self.expr_eval()
            if self.current_char == ')':
                self.advance()
                return result
            else:
                self.error()
        elif self.current_char.isdigit() or (self.current_char == '-' and (self.peek() and self.peek().isdigit())):
            return self.number()
        self.error()

    def term(self):
        result = self.factor()
        while self.current_char is not None and self.current_char in ('*', '/'):
            op = self.current_char
            self.advance()
            if op == '*':
                result *= self.factor()
            elif op == '/':
                divisor = self.factor()
                if divisor == 0:
                    raise ZeroDivisionError("division by zero")
                result /= divisor
        return result

    def expr_eval(self):
        result = self.term()
        while self.current_char is not None and self.current_char in ('+', '-'):
            op = self.current_char
            self.advance()
            if op == '+':
                result += self.term()
            elif op == '-':
                result -= self.term()
        return result

    def peek(self):
        peek_pos = self.pos + 1
        if peek_pos < len(self.expr):
            return self.expr[peek_pos]
        return None

def evaluate(expr: str) -> float:
    """Evaluates an arithmetic expression using a recursive descent parser."""
    evaluator = Evaluator(expr)
    evaluator.skip_whitespace()
    result = evaluator.expr_eval()
    if evaluator.current_char is not None:
